/* Edit Video — motion graphic runtime. Deterministic: render(t) draws the exact frame for time t (seconds). */
const W = 1080, H = 1920;
const E = {
  lin: x => x,
  out: x => 1 - Math.pow(1 - x, 3),
  in: x => x * x * x,
  io: x => x < .5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2,
  back: x => { const c = 1.7; return 1 + (c + 1) * Math.pow(x - 1, 3) + c * Math.pow(x - 1, 2); },
  elastic: x => x === 0 || x === 1 ? x : Math.pow(2, -10 * x) * Math.sin((x * 10 - .75) * (2 * Math.PI / 3)) + 1,
};
const clamp = (x, a = 0, b = 1) => Math.max(a, Math.min(b, x));
const prog = (t, start, dur, ease = 'out') => E[ease](clamp((t - start) / dur));
const lerp = (a, b, p) => a + (b - a) * p;
function el(tag, cls, parent, html) {
  const e = document.createElement(tag); if (cls) e.className = cls;
  if (html !== undefined) e.innerHTML = html; if (parent) parent.appendChild(e); return e;
}
function svgEl(tag, attrs, parent) {
  const e = document.createElementNS('http://www.w3.org/2000/svg', tag);
  for (const k in attrs) e.setAttribute(k, attrs[k]); if (parent) parent.appendChild(e); return e;
}
function icon(name, size = 64, color = 'currentColor', stroke = 2) {
  const s = (window.ICONS || {})[name]; if (!s) return '';
  return s.replace(/<!--.*?-->/s, '').replace(/width="24"/, `width="${size}"`).replace(/height="24"/, `height="${size}"`)
          .replace(/stroke="currentColor"/, `stroke="${color}"`).replace(/stroke-width="2"/, `stroke-width="${stroke}"`);
}
/* *emphasis* -> span.em */
const rich = s => String(s ?? '').replace(/\*(.+?)\*/g, '<span class="em">$1</span>');
/* style helper */
const S = (e, o) => { for (const k in o) e.style[k] = o[k]; return e; };
const T = (e, x = 0, y = 0, sc = 1, rot = 0) => { e.style.transform = `translate(${x}px,${y}px) scale(${sc}) rotate(${rot}deg)`; };
/* appear: fade + rise + scale; returns p */
function appear(e, t, start, dur = .45, dy = 40, from = .92, ease = 'back') {
  const p = prog(t, start, dur, ease), o = prog(t, start, dur * .6, 'out');
  e.style.opacity = o; T(e, 0, (1 - p) * dy, lerp(from, 1, p)); return p;
}
function exitAll(root, t, dur, len = .35) {
  const p = prog(t, dur - len, len, 'in'); root.style.opacity = 1 - p; root.style.transform = `scale(${1 - .04 * p})`; }
const SFX = []; const cue = (t, kind, vol) => SFX.push([+t.toFixed(3), kind, vol ?? 1]);

window.MG = {
  init(cfg) {
    const th = cfg.theme, root = document.getElementById('root');
    window.ICONS = cfg.icons || {}; window.TEXTFX = cfg.textfx || window.TEXTFX || {};
    const st = document.documentElement.style;
    for (const k in th) if (typeof th[k] === 'string') st.setProperty('--' + k, th[k]);
    document.body.classList.add('mode-' + cfg.mode, 'pos-' + (cfg.pos || 'center'));
    if (cfg.mode === 'full') root.classList.add('bg');
    const tpl = window.TEMPLATES[cfg.template];
    if (!tpl) throw new Error('template not found: ' + cfg.template);
    const stage = el('div', 'stage', root);
    this.render_fn = tpl.build(stage, cfg.data || {}, th, cfg.dur || tpl.dur || 3);
    this.dur = cfg.dur || Math.max(tpl.dur || 3, stage._minDur || 0);
    this.root = root; this.stage = stage;
    return { dur: this.dur, sfx: SFX, min_dur: Math.max(tpl.dur || 3, stage._minDur || 0) };
  },
  render(t) {
    this.render_fn(t);
    if (this.root.classList.contains('bg')) {
      const pin = prog(t, 0, .35, 'out'), pout = prog(t, this.dur - .3, .3, 'in');
      this.root.style.clipPath = pout > 0 ? `circle(${lerp(150, 0, pout)}% at 50% 50%)` : `circle(${lerp(0, 150, pin)}% at 50% 50%)`;
    } else if (!this.stage._ownExit) exitAll(this.stage, t, this.dur);
  },
};



/* Edit Video — motion graphic templates (original designs).
   Each: {dur, desc, example, build(stage, data, theme, dur) -> render(t)}.
   Items accept optional "at" (seconds from template start) to sync with speech. */
window.TEMPLATES = {};
const TP = window.TEMPLATES;
const at = (it, k, base, step) => (it && typeof it === 'object' && typeof it.at === 'number') ? it.at : base + k * step;

/* 1. TITLE — kinetic title, words rise from blur, *emphasis* gets a marker sweep */
TP.title = {
  dur: 2.6, desc: 'Tiêu đề lớn, từng chữ bay lên từ mờ; *chữ* nhấn có vệt màu quét. Hook, tên phần.',
  example: { text: 'Bí mật *tính năng* mới', sub: 'Phần 1' },
  build(stage, d, th) {
    const box = el('div', '', stage); S(box, { textAlign: 'center' });
    let sub; if (d.sub) { sub = el('div', 'tag', box, d.sub); S(sub, { marginBottom: '40px' }); }
    const h = el('div', 'h', box); S(h, { fontSize: (d.size || 112) + 'px', lineHeight: 1.12 });
    const words = []; let em = false;
    String(d.text || '').split(/(\*)/).forEach(part => {
      if (part === '*') { em = !em; return; }
      part.split(' ').filter(Boolean).forEach(w => {
        const s = el('span', '', h); S(s, { display: 'inline-block', margin: '0 14px', position: 'relative' });
        if (em) { const m = el('span', '', s); S(m, { position: 'absolute', left: '-6px', right: '-6px', bottom: '-6px', height: '16px', background: 'var(--accent)', zIndex: 0, borderRadius: '10px', transformOrigin: 'left' }); s.mark = m; }
        const tx = el('span', '', s, w); S(tx, { position: 'relative', zIndex: 1, color: em ? 'var(--accent)' : 'var(--fg)' }); words.push(s);
      });
    });
    words.forEach((w, k) => cue(.15 + k * .09, k % 2 ? 'pop-soft' : 'tick', .6));
    if (sub) cue(0, 'swish');
    stage._minDur = .15 + words.length * .09 + 1.4;
    return t => {
      if (sub) appear(sub, t, 0, .4, -30);
      words.forEach((w, k) => {
        const s0 = .15 + k * .09, p = prog(t, s0, .5, 'back'), o = prog(t, s0, .3);
        w.style.opacity = o; w.style.filter = `blur(${(1 - o) * 14}px)`; T(w, 0, (1 - p) * 70, lerp(.8, 1, p));
        if (w.mark) w.mark.style.transform = `scaleX(${prog(t, s0 + .25, .35, 'io')})`;
      });
    };
  }
};

