/* ---------------- hoạ hình tối giản (doodle) ---------------- */
/* nét vẽ tay: path tự vẽ ra theo thời gian */
function drawPath(svg, d, color, w, t, start, dur) {
  const p = svgEl('path', { d, fill: 'none', stroke: color, 'stroke-width': w, 'stroke-linecap': 'round', 'stroke-linejoin': 'round' }, svg);
  const L = p.getTotalLength(); p.setAttribute('stroke-dasharray', L); p._L = L; p._s = start; p._d = dur;
  return p;
}
const drawUpd = (p, t) => p.setAttribute('stroke-dashoffset', p._L * (1 - prog(t, p._s, p._d, 'io')));

