/* 22. CUTLINE — sóng âm, khoảng lặng bị cắt bỏ */
TP.cutline = {
  dur: 3.4, desc: 'Sóng âm thanh, các khoảng lặng (đỏ) bị kéo kéo cắt rồi dồn lại. Cắt ngừng nghỉ, tối ưu thời lượng.',
  example: { title: 'Cắt *khoảng lặng*', before: '19.5s', after: '12.0s' },
  build(stage, d) {
    const title = el('div', 'h title', stage, rich(d.title));
    const box = el('div', 'panel', stage); S(box, { width: '100%', height: '420px', position: 'relative', overflow: 'hidden' });
    const N = 64, bars = [], gaps = new Set([9, 10, 11, 25, 26, 40, 41, 42, 43, 55, 56]);
    const rnd = i => (Math.sin(i * 12.9898) * 43758.5453) % 1;
    for (let i = 0; i < N; i++) {
      const b = el('div', '', box); const g = gaps.has(i); const h = g ? 10 : 60 + Math.abs(rnd(i)) * 220;
      S(b, { position: 'absolute', bottom: (210 - h / 2) + 'px', width: '10px', height: h + 'px', borderRadius: '6px', background: g ? 'var(--accent2)' : 'var(--accent)' }); bars.push({ b, g, i });
    }
    const lab = el('div', 'h', stage); S(lab, { fontSize: '72px', marginTop: '40px' });
    lab.innerHTML = `<span class="muted" style="text-decoration:line-through">${d.before || ''}</span>  →  <span class="em">${d.after || ''}</span>`;
    cue(.9, 'swish', .8); cue(1.4, 'swish', .6); cue(1.9, 'impact', .4);
    return t => {
      appear(title, t, 0, .4, 30); appear(box, t, .1, .45, 40, .96);
      const p = prog(t, .9, 1.0, 'io'); let x = 30; const step = 14.2;
      bars.forEach(({ b, g, i }) => {
        const vis = g ? 1 - p : 1; b.style.opacity = vis; b.style.transform = `scaleY(${g ? 1 - p : 1})`;
        b.style.left = x + 'px'; x += step * (g ? (1 - p) : 1);
      });
      appear(lab, t, 1.9, .45, 30);
    };
  }
};

