        const half = (top) => { const h = el('div', '', c); S(h, { position: 'absolute', left: 0, right: 0, height: '50%', [top ? 'top' : 'bottom']: 0, overflow: 'hidden', background: top ? 'color-mix(in srgb,var(--surface) 92%,#fff)' : 'var(--surface)', borderRadius: top ? '26px 26px 0 0' : '0 0 26px 26px', boxShadow: '0 20px 40px rgba(0,0,0,.35)' });
          const n = el('div', '', h); S(n, { position: 'absolute', left: 0, right: 0, height: '270px', lineHeight: '270px', textAlign: 'center', [top ? 'top' : 'bottom']: 0 }); h.n = n; return h; };
        c.topS = half(true); c.botS = half(false);
        c.flap = half(true); S(c.flap, { transformOrigin: 'bottom', zIndex: 3, backfaceVisibility: 'hidden' });
        const line = el('div', '', c); S(line, { position: 'absolute', left: 0, right: 0, top: '134px', height: '3px', background: 'rgba(0,0,0,.55)', zIndex: 5 });
        return c;
